import random


class SudokuBoard:
    """A 9x9 Sudoku board with unique-solution puzzle generation."""

    def __init__(self, seed=None, holes=45):
        self.rng = random.Random(seed)
        self.solution = [[0] * 9 for _ in range(9)]
        self.grid = [[0] * 9 for _ in range(9)]
        self.given = [[False] * 9 for _ in range(9)]
        self._generate(holes)

    # -- generation ---------------------------------------------------
    def _valid(self, grid, r, c, v):
        for i in range(9):
            if grid[r][i] == v or grid[i][c] == v:
                return False
        br, bc = 3 * (r // 3), 3 * (c // 3)
        for i in range(br, br + 3):
            for j in range(bc, bc + 3):
                if grid[i][j] == v:
                    return False
        return True

    def _fill(self, grid, pos=0):
        if pos == 81:
            return True
        r, c = divmod(pos, 9)
        if grid[r][c]:
            return self._fill(grid, pos + 1)
        values = list(range(1, 10))
        self.rng.shuffle(values)
        for v in values:
            if self._valid(grid, r, c, v):
                grid[r][c] = v
                if self._fill(grid, pos + 1):
                    return True
                grid[r][c] = 0
        return False

    def _count_solutions(self, grid, limit=2):
        found = [0]

        def solve(pos):
            if found[0] >= limit:
                return True
            if pos == 81:
                found[0] += 1
                return found[0] >= limit
            r, c = divmod(pos, 9)
            if grid[r][c]:
