        return found[0]

    def _generate(self, holes):
        self._fill(self.solution)
        puzzle = [row[:] for row in self.solution]
        cells = list(range(81))
        self.rng.shuffle(cells)
        removed = 0
        for cell in cells:
            if removed >= holes:
                break
            r, c = divmod(cell, 9)
