"""Sudoku game logic: unique-solution puzzle generation, validation, display."""

import random


class SudokuBoard:
    """A 9x9 Sudoku board whose rows, columns and 3x3 boxes hold 1-9 once."""

    def __init__(self, seed=None, holes=45):
        self.rng = random.Random(seed)
        self.solution = [[0] * 9 for _ in range(9)]
        self.grid = [[0] * 9 for _ in range(9)]
        self.given = [[False] * 9 for _ in range(9)]
        self._generate(holes)

    def _valid(self, grid, r, c, v):
        for i in range(9):
            if grid[r][i] == v or grid[i][c] == v:
                return False
        br, bc = 3 * (r // 3), 3 * (c // 3)
        for i in range(br, br + 3):
            for j in range(bc, bc + 3):
                if grid[i][j] == v:
                    return False
        return True

    def _fill(self, grid, pos=0):
        if pos == 81:
            return True
        r, c = divmod(pos, 9)
        if grid[r][c]:
            return self._fill(grid, pos + 1)
        values = list(range(1, 10))
        self.rng.shuffle(values)
        for v in values:
            if self._valid(grid, r, c, v):
                grid[r][c] = v
                if self._fill(grid, pos + 1):
                    return True
                grid[r][c] = 0
        return False

    def _count_solutions(self, grid, limit=2):
        found = [0]

        def solve(pos):
            if found[0] >= limit:
                return True
            if pos == 81:
                found[0] += 1
                return found[0] >= limit
            r, c = divmod(pos, 9)
            if grid[r][c]:
                return solve(pos + 1)
            for v in range(1, 10):
                if self._valid(grid, r, c, v):
                    grid[r][c] = v
                    if solve(pos + 1):
                        grid[r][c] = 0
                        return True
                    grid[r][c] = 0
            return False

        solve(0)
        return found[0]

    def _generate(self, holes):
        self._fill(self.solution)
        puzzle = [row[:] for row in self.solution]
        cells = list(range(81))
        self.rng.shuffle(cells)
        removed = 0
        for cell in cells:
            if removed >= holes:
                break
            r, c = divmod(cell, 9)
            backup = puzzle[r][c]
            puzzle[r][c] = 0
            if self._count_solutions([row[:] for row in puzzle]) != 1:
                puzzle[r][c] = backup
            else:
                removed += 1
        self.grid = puzzle
        self.given = [[puzzle[r][c] != 0 for c in range(9)] for r in range(9)]

    def is_given(self, r, c):
        return self.given[r][c]

    def set_cell(self, r, c, v):
        """Set cell (r, c) to v (1-9); v == 0 clears it. True on success."""
        if not (0 <= r < 9 and 0 <= c < 9 and 0 <= v <= 9):
            return False
        if self.given[r][c]:
            return False
        self.grid[r][c] = v
        return True

    def mistakes(self):
        """List of (r, c, value) filled cells that break row/col/box rules."""
        bad = []
        for r in range(9):
            for c in range(9):
                v = self.grid[r][c]
                if not v:
                    continue
                self.grid[r][c] = 0
                if not self._valid(self.grid, r, c, v):
                    bad.append((r, c, v))
                self.grid[r][c] = v
        return bad

    def is_complete(self):
        """True when every cell is filled and no Sudoku rule is violated."""
        if any(self.grid[r][c] == 0 for r in range(9) for c in range(9)):
            return False
        return not self.mistakes()

    def reveal_solution(self):
        self.grid = [row[:] for row in self.solution]
        self.given = [[True] * 9 for _ in range(9)]

    def render(self):
        lines = ["    1 2 3 | 4 5 6 | 7 8 9", "    " + "-" * 21]
        for r in range(9):
            cells = []
            for c in range(9):
                if c in (3, 6):
                    cells.append("|")
                cells.append(str(self.grid[r][c]) if self.grid[r][c] else ".")
            lines.append(f"{r + 1}  " + " ".join(cells))
        return "\n".join(lines)
